// Validates tool input, resolves the window and builds the auth header.
// $env is unavailable in HTTP node expression previews but works here, so
// credentials are read once and passed downstream as plain fields.
// Buffer is likewise available in Code nodes only.

const DEFAULT_DAYS = 30;
const DEFAULT_LIMIT = 5;
const MAX_LIMIT = 50;
const MAX_DAYS = 366;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

const input = $input.first().json ?? {};

const storeUrl = String($env.WOO_STORE_URL || '').replace(/\/+$/, '');
const consumerKey = String($env.WOO_CONSUMER_KEY || '');
const consumerSecret = String($env.WOO_CONSUMER_SECRET || '');
const timezone = String($env.BUSINESS_TIMEZONE || 'Europe/Kyiv');

function fail(status, error) {
  return [{ json: { valid: false, status, error } }];
}

if (!storeUrl || !consumerKey || !consumerSecret) {
  return fail('upstream_error', 'WooCommerce credentials are not configured');
}

function optionalInt(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  return Number(value);
}

const limit = optionalInt(input.limit, DEFAULT_LIMIT);
if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
  return fail('invalid_input', `limit must be an integer between 1 and ${MAX_LIMIT}`);
}

const days = optionalInt(input.days, DEFAULT_DAYS);
if (!Number.isInteger(days) || days < 1 || days > MAX_DAYS) {
  return fail('invalid_input', `days must be an integer between 1 and ${MAX_DAYS}`);
}

let end;
if (input.to) {
  if (!DATE_RE.test(String(input.to))) {
    return fail('invalid_input', 'to must be formatted as YYYY-MM-DD');
  }
  end = DateTime.fromISO(String(input.to), { zone: timezone });
} else {
  end = DateTime.now().setZone(timezone).startOf('day');
}
if (!end.isValid) return fail('invalid_input', 'to is not a valid date');

let start;
if (input.from) {
  if (!DATE_RE.test(String(input.from))) {
    return fail('invalid_input', 'from must be formatted as YYYY-MM-DD');
  }
  start = DateTime.fromISO(String(input.from), { zone: timezone });
} else {
  start = end.minus({ days: days - 1 });
}
if (!start.isValid) return fail('invalid_input', 'from is not a valid date');
if (start > end) return fail('invalid_input', 'from date is later than to date');

// after and before are strictly exclusive in the WooCommerce REST API, so
// the lower bound is nudged back one second to keep an order created
// exactly at local midnight inside the window.
const fmt = "yyyy-MM-dd'T'HH:mm:ss";
const after = start.startOf('day').minus({ seconds: 1 }).toUTC().toFormat(fmt);
const before = end.startOf('day').plus({ days: 1 }).toUTC().toFormat(fmt);

const authHeader =
  'Basic ' + Buffer.from(`${consumerKey}:${consumerSecret}`).toString('base64');

return [
  {
    json: {
      valid: true,
      ordersUrl: `${storeUrl}/wp-json/wc/v3/orders`,
      authHeader,
      after,
      before,
      timezone,
      limit,
      from: start.toFormat('yyyy-MM-dd'),
      to: end.toFormat('yyyy-MM-dd'),
    },
  },
];

// Mirrors the error contract of get_orders_summary so the agent sees one
// shape across tools.
const source = $input.first().json ?? {};
return [
  {
    json: {
      status: source.status || 'invalid_input',
      error: source.error || 'invalid input',
      top: [],
    },
  },
];

// Turns the order list into one item per refunded order, which is what
// makes the next HTTP node fire once per order. The loop is expressed as
// data shape rather than written out.
//
// Always Output Data on the previous node injects a single empty item when
// a page comes back empty, so items without an id are filtered out here.
//
// SOLD_STATUSES intentionally includes "refunded": for an inventory
// question the unit was still sold before it came back. This differs from
// the revenue statuses used by get_orders_summary.

const SOLD_STATUSES = ['pending', 'processing', 'on-hold', 'completed', 'refunded'];

const config = $('prepare-request').first().json;
const orders = $input.all().map((item) => item.json).filter((order) => order && order.id);

let excludedByStatus = 0;
const selected = [];

for (const order of orders) {
  const refunds = order.refunds || [];
  if (refunds.length === 0) continue;
  if (!SOLD_STATUSES.includes(order.status)) {
    excludedByStatus += 1;
    continue;
  }
  selected.push({
    json: {
      orderId: order.id,
      orderStatus: order.status,
      refundsUrl: `${config.ordersUrl}/${order.id}/refunds`,
      authHeader: config.authHeader,
      ordersScanned: orders.length,
      excludedByStatus,
    },
  });
}

if (selected.length === 0) {
  return [{ json: { noRefunds: true, ordersScanned: orders.length, excludedByStatus } }];
}

// The counter is only final after the whole scan, so stamp it on every item.
for (const item of selected) {
  item.json.excludedByStatus = excludedByStatus;
  item.json.refundedOrders = selected.length;
}

return selected;

// Aggregates refund line items per product and emits the tool contract.
//
// Money is accumulated as integer cents. The Python reference does the same,
// which is what makes a to-the-cent comparison meaningful rather than lucky:
// float accumulation drifts differently in the two runtimes.
//
// The detail endpoint names a refund's total "amount"; the array embedded in
// GET /orders names the same value "total". Reading the wrong one silently
// yields zero.

const MIN_SALES_FOR_RATE = 3;
const UNSPECIFIED_REASON = 'unspecified';
const SOLD_STATUSES = ['pending', 'processing', 'on-hold', 'completed', 'refunded'];

const config = $('prepare-request').first().json;
const selection = $('select-refunded-orders').first().json;

const window = {
  from: config.from,
  to: config.to,
  timezone: config.timezone,
  attribution: 'order_date',
  orders_scanned: selection.ordersScanned || 0,
};

if (selection.noRefunds) {
  return [{ json: { status: 'no_data', window, limit: config.limit } }];
}

function toCents(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.abs(Math.round(parsed * 100)) : 0;
}

function toUnits(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.abs(Math.trunc(parsed)) : 0;
}

function normaliseReason(value) {
  if (typeof value !== 'string' || value.trim() === '') return UNSPECIFIED_REASON;
  return value.trim();
}

function refundType(refund) {
  for (const meta of refund.meta_data || []) {
    if (meta && meta.key === '_refund_type') return String(meta.value || 'unknown');
  }
  return 'unknown';
}

// Units sold per product, the return-rate denominator, from orders already
// in memory. No second round trip to the API.
const soldByProduct = new Map();
for (const item of $('fetch-orders').all()) {
  const order = item.json;
  if (!order || !order.id || !SOLD_STATUSES.includes(order.status)) continue;
  for (const line of order.line_items || []) {
    const productId = Number(line.product_id) || 0;
    if (!productId) continue;
    soldByProduct.set(productId, (soldByProduct.get(productId) || 0) + toUnits(line.quantity));
  }
}

const products = new Map();
const globalReasons = new Map();

let refundsCount = 0;
let ordersAffected = 0;
let refundCents = 0;
let unitsReturned = 0;
let fullRefunds = 0;
let partialRefunds = 0;
let nonProductLines = 0;
let amountMismatches = 0;
let detailCalls = 0;

const items = $input.all();

for (let index = 0; index < items.length; index += 1) {
  const payload = items[index].json;
  // The paired input item carries the order id: the HTTP node preserves
  // input order one-to-one.
  const source = $('select-refunded-orders').all()[index];
  if (!source) continue;
  const orderId = source.json.orderId;
  if (!orderId) continue;
  detailCalls += 1;

  // A single refund object arrives as an object; several arrive as an array.
  let refunds = [];
  if (Array.isArray(payload)) refunds = payload;
  else if (Array.isArray(payload.data)) refunds = payload.data;
  else if (payload && payload.id) refunds = [payload];
  if (refunds.length === 0) continue;
  ordersAffected += 1;

  for (const refund of refunds) {
    refundsCount += 1;
    const reason = normaliseReason(refund.reason);
    globalReasons.set(reason, (globalReasons.get(reason) || 0) + 1);

    const kind = refundType(refund);
    if (kind === 'full') fullRefunds += 1;
    else if (kind === 'partial') partialRefunds += 1;

    const declared = toCents(refund.amount);
    let lineSum = 0;

    for (const line of refund.line_items || []) {
      const cents = toCents(line.total);
      const units = toUnits(line.quantity);
      lineSum += cents;

      const productId = Number(line.product_id) || 0;
      if (!productId) {
        nonProductLines += 1;
        continue;
      }

      let entry = products.get(productId);
      if (!entry) {
        entry = {
          product_id: productId,
          sku: String(line.sku || ''),
          name: String(line.name || ''),
          units_returned: 0,
          refund_cents: 0,
          order_ids: new Set(),
          reasons: new Map(),
        };
        products.set(productId, entry);
      }
      entry.units_returned += units;
      entry.refund_cents += cents;
      entry.order_ids.add(orderId);
      entry.reasons.set(reason, (entry.reasons.get(reason) || 0) + 1);
      unitsReturned += units;
    }

    refundCents += lineSum;
    if (declared && Math.abs(declared - lineSum) > 1) amountMismatches += 1;
  }
}

if (products.size === 0) {
  return [{ json: { status: 'no_data', window, limit: config.limit } }];
}

function sortedCounter(counter) {
  return Object.fromEntries([...counter.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])));
}

const rows = [...products.values()].map((entry) => {
  const unitsSold = soldByProduct.get(entry.product_id) || 0;
  const rate = unitsSold ? Math.round((entry.units_returned / unitsSold) * 10000) / 100 : 0;
  const reasons = sortedCounter(entry.reasons);
  const topReason = Object.keys(reasons)[0] || UNSPECIFIED_REASON;
  return {
    product_id: entry.product_id,
    sku: entry.sku,
    name: entry.name,
    units_returned: entry.units_returned,
    refund_amount: Math.round(entry.refund_cents) / 100,
    orders_affected: entry.order_ids.size,
    units_sold: unitsSold,
    return_rate_pct: rate,
    rate_significant: unitsSold >= MIN_SALES_FOR_RATE,
    top_reason: topReason,
    reasons,
  };
});

// Money first: on a small refund set the unit counter ties almost
// everywhere, which would make the ranking arbitrary.
rows.sort((a, b) => {
  const byMoney = Math.round(b.refund_amount * 100) - Math.round(a.refund_amount * 100);
  if (byMoney !== 0) return byMoney;
  const byUnits = b.units_returned - a.units_returned;
  if (byUnits !== 0) return byUnits;
  return a.product_id - b.product_id;
});

const top = rows.slice(0, config.limit).map((row, position) => ({ rank: position + 1, ...row }));

return [
  {
    json: {
      status: 'ok',
      window,
      totals: {
        refunds_count: refundsCount,
        orders_affected: ordersAffected,
        refund_amount: Math.round(refundCents) / 100,
        units_returned: unitsReturned,
        full_refunds: fullRefunds,
        partial_refunds: partialRefunds,
        products_affected: products.size,
        reasons: sortedCounter(globalReasons),
      },
      diagnostics: {
        detail_calls: detailCalls,
        excluded_by_status: selection.excludedByStatus || 0,
        non_product_lines: nonProductLines,
        amount_mismatches: amountMismatches,
      },
      top,
      limit: config.limit,
    },
  },
];
